// Behavioural stubs of the tile's analog blocks for the TT-level cocotb tests (test/test.py).
// Port lists are the LVS source's subcircuits (lvs/tt_um_mattvenn_gf433_vco.spice); the wrapper that wires them is
// generated by tools/check_pinout.py --verilog. They are logic models only: enough to see that each control line
// from the TT pins or the macro reaches the right block, not a model of the analog behaviour.
// Values the test sets or reads are plain regs / wires inside the stubs (e.g. xvco_core.osc, xrx_bb_i.val).
`default_nettype none
`timescale 1ns / 1ps

// ring VCO + level shifter + /4: ck (f / 4) and ls (the LO) come from osc, which the test toggles
module vco_core (input wire VDD, input wire VDD_LS, input wire VSS, input wire vctrl,
                 input wire bit0, input wire bit1, input wire bit2, input wire bit3, input wire bit4,
                 input wire bitb0, input wire bitb1, input wire bitb2, input wire bitb3, input wire bitb4,
                 output wire ck, input wire vg, output wire ls, input wire vbnf, output wire a2);
    reg osc = 1'b0;
    wire [4:0] code  = {bit4, bit3, bit2, bit1, bit0};
    wire [4:0] codeb = {bitb4, bitb3, bitb2, bitb1, bitb0};
    wire       code_ok = (codeb === ~code);     // the coarse DAC's switch pairs see complementary drive
    assign ck = osc;
    assign ls = osc;
    assign a2 = osc;
endmodule

module cgm_ref (input wire VDD, input wire VSS, inout wire vbn, output wire vbnf);
    assign vbnf = 1'b1;
endmodule

module decap_ls (input wire VDD_LS, input wire VSS); endmodule
module rx_decap (input wire VDD, input wire VSS); endmodule
module ant_row1 (input wire VDD, input wire VSS, input wire a0); endmodule
module ant_row2 (input wire VDD, input wire VSS, input wire a0, input wire a1); endmodule
module ant_row4 (input wire VDD, input wire VSS, input wire a0, input wire a1, input wire a2, input wire a3);
endmodule

// medium current DAC: the word it is set to, from its active-low lines (ns1..ns31 thermometer, nb0..nb4, nsd)
module mdac (input wire VDD, input wire VSS, output wire vg, input wire vbnf,
             input wire ns30, input wire ns28, input wire ns26, input wire ns24, input wire ns22, input wire ns20,
             input wire ns18, input wire ns16, input wire ns14, input wire ns12, input wire ns10, input wire ns8,
             input wire ns6, input wire ns4, input wire ns2, input wire nb4, input wire nb2, input wire nb0,
             input wire nsd, input wire nb1, input wire nb3, input wire ns1, input wire ns3, input wire ns5,
             input wire ns7, input wire ns9, input wire ns11, input wire ns13, input wire ns15, input wire ns17,
             input wire ns19, input wire ns21, input wire ns23, input wire ns25, input wire ns27, input wire ns29,
             input wire ns31);
    wire [30:0] seg = ~{ns31, ns30, ns29, ns28, ns27, ns26, ns25, ns24, ns23, ns22, ns21, ns20, ns19, ns18, ns17,
                        ns16, ns15, ns14, ns13, ns12, ns11, ns10, ns9, ns8, ns7, ns6, ns5, ns4, ns3, ns2, ns1};
    wire [4:0]  bin = ~{nb4, nb3, nb2, nb1, nb0};
    wire        sd  = ~nsd;
    integer nseg, k;
    always @* begin
        nseg = 0;
        for (k = 0; k < 31; k = k + 1) nseg = nseg + seg[k];
    end
    wire [9:0] word = nseg * 32 + bin;          // segments on x 32 LSB + the binary part
    wire       thermo_ok = (seg == ((31'd1 << nseg) - 1));   // segments on from ns1 upwards, no gaps
    assign vg = 1'b0;
endmodule

// vctrl pull-down (200 kOhm to VGND): a weak 0 that ua[0] can override through the debug switch
module vctrl_pd (inout wire a, input wire b);
    assign (weak0, weak1) a = 1'b0;
endmodule

module bits_inv (input wire VDD, input wire VSS, input wire in0, input wire in1, input wire in2, input wire in3,
                 input wire in4, output wire out0, output wire out1, output wire out2, output wire out3,
                 output wire out4);
    assign {out4, out3, out2, out1, out0} = ~{in4, in3, in2, in1, in0};
endmodule

// TX driver: each arm passes the LO while its enable is high, else it is held low
module tx_drv (input wire VDD, input wire VSS, input wire ls, input wire en_p, input wire en_n,
               output wire out_p, output wire out_n);
    assign out_p = en_p & ls;
    assign out_n = en_n & ~ls;
endmodule

// receiver: enb = ~en; with the receiver off, the bias, LO and limiter outputs are 0
module rx_bias (input wire VDD, input wire VSS, input wire en, output wire enb, output wire nb);
    reg val = 1'b1;                              // the bias level, as a logic stand-in
    assign enb = ~en;
    assign nb = en & val;
endmodule

module rx_lna (input wire VDD, input wire VSS, input wire inp, input wire inn, output wire oip, output wire oin,
               output wire oqp, output wire oqn, input wire nb, input wire enb);
    assign {oip, oin, oqp, oqn} = enb ? 4'b0000 : {inp, inn, inp, inn};
endmodule

module rx_lsq (input wire VDD, input wire VSS, input wire aq, input wire qenb, output wire lsq);
    assign lsq = ~qenb & aq;
endmodule

module rx_lobuf (input wire VDD, input wire VSS, input wire in, input wire en, output wire lo, output wire lob);
    assign lo = en & in;
    assign lob = en & ~in;
endmodule

module rx_mix (input wire VDD, input wire VSS, input wire rfp, input wire rfn, output wire bbp, output wire bbn,
               input wire lo, input wire lob);
    assign bbp = 1'b0;
    assign bbn = 1'b0;
endmodule

// baseband amplifier: outp / outn = val / ~val while enabled (the test sets val per arm)
module rx_bb (input wire VDD, input wire VSS, input wire inp, input wire inn, output wire outp, output wire outn,
              input wire nb, input wire enb);
    reg val = 1'b0;
    assign outp = enb ? 1'b0 : val;
    assign outn = enb ? 1'b0 : ~val;
endmodule

module rx_lim (input wire VDD, input wire VSS, input wire inp, input wire inn, output wire q, input wire nb,
               input wire enb);
    assign q = enb ? 1'b0 : (inp & ~inn);
endmodule

// debug switch: a transmission gate between mod and bus while ctrl is high
module dbg_tg (input wire VDD, input wire VSS, input wire ctrl, inout wire mod, inout wire bus);
    tranif1 tg (mod, bus, ctrl);
endmodule
